#!/usr/bin/env -S cargo -Zscript
---
[package]
edition = "2024"

[dependencies]
mantle-rust-plan-core = { path = "../signed-stagex-adoption-dev-20261116/crates/mantle-rust-plan-core" }
serde_json = "=1.0.149"
---
use std::io::Read;
use mantle_rust_plan_core::{NativeTargetCandidate, admit_native_targets};
fn main() {
    const MAX_BYTES: u64 = 1_048_576;
    let mut bytes = Vec::new();
    std::io::stdin().take(MAX_BYTES + 1).read_to_end(&mut bytes).unwrap();
    assert!(bytes.len() as u64 <= MAX_BYTES);
    let candidates: Vec<NativeTargetCandidate> = serde_json::from_slice(&bytes).unwrap();
    let admitted = admit_native_targets("path+captured-tools-fixture#mantle@0.1.0", candidates).unwrap();
    for name in ["adopt-source-built-stagex", "check-native-row-receipts"] {
        let target = admitted.iter().find(|target| target.name == name).unwrap();
        assert_eq!(target.kind, "bin");
        assert!(target.source_path.contains("/tools/"));
    }
    println!("{}", serde_json::to_string(&admitted).unwrap());
}
